{
  "service": "mock-api",
  "description": "mock-api edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8081
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "pricing",
      "host": "pricing.internal",
      "port": 8868,
      "weight": 2,
      "health_check": "/healthz"
    },
    {
      "name": "shipping",
      "host": "shipping.internal",
      "port": 9623,
      "weight": 8,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 8830,
      "weight": 9,
      "health_check": "/healthz"
    },
    {
      "name": "catalog",
      "host": "catalog.internal",
      "port": 7032,
      "weight": 3,
      "health_check": "/healthz"
    },
    {
      "name": "reviews",
      "host": "reviews.internal",
      "port": 7693,
      "weight": 6,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/catalog/tokens",
      "upstream": "catalog",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1500,
      "retries": 1
    },
    {
      "path": "/api/v1/reviews/quotes",
      "upstream": "reviews",
      "methods": [
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 0
    },
    {
      "path": "/api/v1/catalog/labels",
      "upstream": "catalog",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 1000,
      "retries": 1
    },
    {
      "path": "/api/v1/shipping/audit",
      "upstream": "shipping",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1500,
      "retries": 1
    },
    {
      "path": "/api/v1/search/audit",
      "upstream": "search",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 2000,
      "retries": 1
    },
    {
      "path": "/api/v1/catalog/audit",
      "upstream": "catalog",
      "methods": [
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 1
    }
  ]
}
